import{_ as t,o as h,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Lịch sử · Địa lý","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/lich-su-dia-ly.md","filePath":"ideas/inquiry-ib/lich-su-dia-ly.md"}'),a={name:"ideas/inquiry-ib/lich-su-dia-ly.md"};function c(g,n,u,e,r,s){return h(),i("div",null,[...n[0]||(n[0]=[o('<h1 id="lich-su-·-đia-ly" tabindex="-1">Lịch sử · Địa lý <a class="header-anchor" href="#lich-su-·-đia-ly" aria-label="Permalink to &quot;Lịch sử · Địa lý&quot;">​</a></h1><p>Trên trang này# Lịch sử · Địa lý — ba bài học inquiry theo IB <a href="#lich-su-·-đia-ly-—-ba-bai-hoc-inquiry-theo-ib">​</a> Trong IB, nhóm môn này gọi là <strong>Individuals and Societies</strong> — và nó được dạy như một môn <strong>điều tra</strong>, không phải một môn học thuộc. Đây là môn mà inquiry tạo khác biệt lớn nhất — vì lịch sử học thuộc và lịch sử như một môn điều tra là hai môn hoàn toàn khác nhau. Ý xuyên suốt cả mônCâu hỏi trung tâm không phải &quot;chuyện gì đã xảy ra&quot;, mà &quot;làm sao ta biết điều đó — và vì sao các nguồn lại kể khác nhau&quot;. Cũng quan trọng — nhưng không phải ý lớn nhất- Sự kiện lớn hiếm khi có một nguyên nhân duy nhất, và việc chọn nguyên nhân nào quan trọng nhất tự nó đã là một quan điểm.</p><ul><li>Các nhân chứng kể khác nhau mà không ai nói dối — trí nhớ vốn hoạt động như vậy.</li><li>Những quá trình toàn cầu để lại dấu vết rất cụ thể ở địa phương, và các dấu vết đó đo được.</li></ul><h2 id="demo-1-—-nguon-su-lieu-nam-nguoi-ke-mot-su-kien-​" tabindex="-1">Demo 1 — Nguồn sử liệu: năm người kể, một sự kiện <a href="#demo-1-—-nguon-su-lieu-nam-nguoi-ke-mot-su-kien">​</a> <a class="header-anchor" href="#demo-1-—-nguon-su-lieu-nam-nguoi-ke-mot-su-kien-​" aria-label="Permalink to &quot;Demo 1 — Nguồn sử liệu: năm người kể, một sự kiện [​](#demo-1-—-nguon-su-lieu-nam-nguoi-ke-mot-su-kien)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Perspective<strong>Related concepts</strong>Evidence · Perspective · Significance<strong>Global context</strong>Orientation in space and time<strong>Statement of inquiry</strong>Hiểu biết về quá khứ được xây từ những nguồn không hoàn hảo, mỗi nguồn mang lợi ích và giới hạn riêng.<strong>Cần biết trước</strong>Khái niệm nguồn sơ cấp và thứ cấp</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Nguồn sơ cấp là gì? Nguồn thứ cấp là gì?</li><li><strong>Conceptual:</strong> Vì sao hai nguồn cùng thời lại mâu thuẫn nhau?</li><li><strong>Debatable:</strong> Có thể viết một cuốn sử &quot;khách quan&quot; không?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Mô phỏng ngay trong lớp (12 phút).</strong> Giáo viên dàn dựng trước một tình huống ngắn: giữa tiết, một học sinh (đã hẹn trước) bước vào, đặt một vật lên bàn, nói một câu, rồi đi ra. Toàn bộ mất 20 giây. <em>&quot;Viết lại chính xác chuyện vừa xảy ra. Bạn ấy mặc gì, nói gì, để lại cái gì, mất bao lâu.&quot;</em> Đọc chéo: các bản khác nhau đáng kể. Có bản nhớ áo xanh, bản nhớ áo trắng. Câu nói được ghi lại theo bốn cách. <em>&quot;Ai nói dối? Không ai cả. Vậy vì sao khác nhau?&quot;</em> Bài học về độ tin cậy của nhân chứng vừa được dạy bằng chính lớp học, và không học sinh nào quên nó. <strong>Bước 2 — Chuyển sang nguồn thật (18 phút).</strong> Giáo viên đưa bốn nguồn về cùng một sự kiện lịch sử: một nhật ký cá nhân · một bản tin báo chí cùng thời · một tấm ảnh · một bài viết trong sách giáo khoa 50 năm sau. Với mỗi nguồn, học sinh điền bảng: Câu hỏiTrả lờiAi tạo ra nguồn này?Cho ai đọc?Nhằm mục đích gì?Người này biết gì mà người khác không biết?Người này <strong>không</strong> thể biết gì?Nguồn này có lý do gì để nói lệch đi không?Sáu câu hỏi này là công cụ chính của môn Lịch sử trong IB, và học sinh dùng lại chúng suốt nhiều năm. <strong>Bước 3 — Dựng lại sự kiện (15 phút).</strong><em>&quot;Dùng cả bốn nguồn, viết một đoạn kể lại sự kiện. Chỗ nào các nguồn mâu thuẫn, em phải nói rõ là chúng mâu thuẫn — không được chọn bừa một bên.&quot;</em> Yêu cầu cuối là điểm mấu chốt. Học sinh học được rằng <strong>thừa nhận sự không chắc chắn là một phần của công việc sử học</strong>, không phải một điểm yếu cần giấu. <strong>Bước 4 — Tranh luận (10 phút).</strong><em>&quot;Sách giáo khoa của em có phải một nguồn không? Ai viết nó, cho ai đọc, nhằm mục đích gì?&quot;</em> Câu hỏi này làm nhiều giáo viên e ngại. Trong khung IB, nó là câu hỏi hoàn toàn bình thường và được khuyến khích.</p><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này<strong>A — Knowing &amp; understanding</strong>Nắm được sự kiện và bối cảnh<strong>B — Investigating</strong>Đặt câu hỏi tốt về nguồn, tìm thêm nguồn<strong>C — Communicating</strong>Bài viết có dẫn nguồn rõ ràng<strong>D — Thinking critically</strong>Đánh giá được giá trị và giới hạn của từng nguồn</p><h2 id="demo-2-—-nhan-qua-trong-lich-su-vi-sao-chuyen-đo-xay-ra-​" tabindex="-1">Demo 2 — Nhân quả trong lịch sử: vì sao chuyện đó xảy ra? <a href="#demo-2-—-nhan-qua-trong-lich-su-vi-sao-chuyen-đo-xay-ra">​</a> <a class="header-anchor" href="#demo-2-—-nhan-qua-trong-lich-su-vi-sao-chuyen-đo-xay-ra-​" aria-label="Permalink to &quot;Demo 2 — Nhân quả trong lịch sử: vì sao chuyện đó xảy ra? [​](#demo-2-—-nhan-qua-trong-lich-su-vi-sao-chuyen-đo-xay-ra)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Causality<strong>Related concepts</strong>Significance · Change · Perspective<strong>Global context</strong>Fairness and development<strong>Statement of inquiry</strong>Những sự kiện lớn hiếm khi có một nguyên nhân duy nhất, và việc chọn nguyên nhân nào là quan trọng nhất tự nó là một lựa chọn có quan điểm.<strong>Cần biết trước</strong>Đã học nội dung sự kiện đang bàn</p><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Liệt kê không giới hạn (10 phút).</strong> Chọn một sự kiện lớn đã học. <em>&quot;Liệt kê mọi nguyên nhân em nghĩ ra. Càng nhiều càng tốt, chưa cần xếp hạng.&quot;</em> Lớp thường ra 15–25 nguyên nhân. <strong>Bước 2 — Phân loại (12 phút).</strong> Học sinh nhóm các nguyên nhân theo hai trục: <strong>dài hạn / ngắn hạn</strong> và <strong>kinh tế / chính trị / xã hội / cá nhân</strong>. Bảng hai chiều này khiến các em thấy ngay sự mất cân đối trong danh sách của mình — thường thiếu hẳn nguyên nhân dài hạn, vì chúng ít kịch tính hơn. <strong>Bước 3 — Xếp hạng và bảo vệ (15 phút).</strong><em>&quot;Xếp năm nguyên nhân quan trọng nhất. Nhóm em phải thống nhất được thứ tự.&quot;</em> Tranh luận trong nhóm là phần học chính. Rồi các nhóm so kết quả — và chúng khác nhau. <em>&quot;Ba nhóm xếp ba thứ tự khác nhau. Ai đúng?&quot;</em><strong>Bước 4 — Thử phản thực (12 phút).</strong><em>&quot;Nếu bỏ nguyên nhân số 1 của nhóm em đi — sự kiện có xảy ra không?&quot;</em> Đây là công cụ sắc nhất để kiểm tra một lập luận nhân quả. Nếu sự kiện vẫn xảy ra khi bỏ nguyên nhân đó, thì có lẽ nó không quan trọng như nhóm nghĩ. <strong>Bước 5 — Câu hỏi mở (8 phút).</strong><em>&quot;Một cuốn sách sử của nước A và một cuốn của nước B xếp nguyên nhân khác nhau. Điều đó nói gì về môn Lịch sử?&quot;</em></p><h2 id="demo-3-—-đia-ly-đo-thi-hoa-đieu-tra-ngay-tai-noi-minh-song-​" tabindex="-1">Demo 3 — Địa lý: đô thị hoá, điều tra ngay tại nơi mình sống <a href="#demo-3-—-đia-ly-đo-thi-hoa-đieu-tra-ngay-tai-noi-minh-song">​</a> <a class="header-anchor" href="#demo-3-—-đia-ly-đo-thi-hoa-đieu-tra-ngay-tai-noi-minh-song-​" aria-label="Permalink to &quot;Demo 3 — Địa lý: đô thị hoá, điều tra ngay tại nơi mình sống [​](#demo-3-—-đia-ly-đo-thi-hoa-đieu-tra-ngay-tai-noi-minh-song)&quot;">​</a></h2><p><strong>Lớp</strong>8–11<strong>Key concept</strong>Global interactions<strong>Related concepts</strong>Processes · Sustainability · Management<strong>Global context</strong>Globalization and sustainability<strong>Statement of inquiry</strong>Các quá trình toàn cầu để lại dấu vết cụ thể tại từng địa phương, và những dấu vết đó đo được.<strong>Cần biết trước</strong>Đọc bản đồ, khái niệm mật độ dân số</p><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Bản đồ qua thời gian (12 phút).</strong> Giáo viên đưa ảnh vệ tinh cùng một khu vực ở địa phương, chụp cách nhau 10–20 năm (có sẵn miễn phí trên các dịch vụ bản đồ). <em>&quot;Cái gì đã đổi? Đo thử: bao nhiêu phần trăm diện tích chuyển từ xanh sang xám?&quot;</em><strong>Bước 2 — Học sinh tự đặt câu hỏi điều tra (10 phút).</strong><em>&quot;Từ những gì em thấy, đặt ra một câu hỏi mà em có thể tự trả lời bằng dữ liệu thu được ở khu mình sống.&quot;</em> Câu hỏi học sinh thường đưa ra: Giao thông giờ cao điểm đông hơn ở đâu? Khu nào ít cây xanh nhất? Giá thuê nhà đổi thế nào? Ngập nước xảy ra ở đâu? <strong>Bước 3 — Thu dữ liệu thật (làm ngoài giờ, 1 tuần).</strong> Học sinh chọn phương pháp: đếm xe trong 10 phút ở ba điểm · chụp ảnh theo lưới ô · phỏng vấn 10 người · đo nhiệt độ ở khu có cây và khu không có cây. Giáo viên chỉ kiểm tra một điều trước khi cho triển khai: <em>&quot;Dữ liệu này có trả lời được câu hỏi của em không?&quot;</em><strong>Bước 4 — Xử lý và trình bày (15 phút trên lớp).</strong> Vẽ biểu đồ, đánh dấu lên bản đồ, tính trung bình. Rồi: <em>&quot;Dữ liệu của em có đủ để kết luận không? Em đã đo bao nhiêu lần, vào lúc nào? Nếu đo vào ngày khác thì sao?&quot;</em><strong>Bước 5 — Từ dữ liệu tới đề xuất (12 phút).</strong><em>&quot;Dựa trên phát hiện của em, đề xuất một thay đổi cho khu mình. Ai sẽ được lợi, ai sẽ chịu thiệt, và ai có quyền quyết định điều đó?&quot;</em> Ba câu hỏi cuối là đặc trưng của môn này trong IB: một đề xuất chỉ hoàn chỉnh khi đã tính tới việc <strong>ai được và ai mất</strong>. Điều gia đình dùng được Demo 3 là hoạt động hè rất tốt. Chọn một câu hỏi về chính khu phố nhà mình, đo thật trong một tuần, vẽ biểu đồ. Nó dạy phương pháp điều tra tốt hơn bất kỳ chương sách nào — và trẻ nhớ nó nhiều năm vì nó nói về nơi các em sống. <a href="/ideas/inquiry-ib/nghe-thuat-thiet-ke">Nghệ thuật · Thiết kế →</a></p>',19)])])}const d=t(a,[["render",c]]);export{l as __pageData,d as default};
